"""Integration test for the Postgres table names generated by the application."""

import os
from collections.abc import Callable

import psycopg
import pytest
from etlalchemy.app.api.app import create_app
from etlalchemy.app.bootstrap.contexts import CONTEXT_SPECS
from fastapi.testclient import TestClient

DSN = os.environ.get("TEST_DATABASE_URL") or os.environ.get("ETLALCHEMY_DSN")

pytestmark = [
    pytest.mark.integration,
    pytest.mark.skipif(not DSN, reason="TEST_DATABASE_URL is not set"),
]

def _expected_tables() -> set[str]:
    """Derives the expected tables from the context registry.

    Read-model tables come from each view's own metadata, the event store and
    tracking tables from the application and projection names, so a new context
    is covered without editing a list here.
    """
    tables: set[str] = set()
    for spec in CONTEXT_SPECS:
        tables.update(spec.view_factory.view_class.view_metadata.tables)
        prefix = spec.name
        tables.add(f"{prefix}_application_events")
        tables.add(f"{prefix}_projection_tracking")
    return tables


TABLES = tuple(sorted(_expected_tables()))

OLD_TABLES = (
    "catalogapplication_events",
    "catalogprojection_tracking",
    "ingestionapplication_events",
    "ingestionprojection_tracking",
)


def test_postgres_table_names_are_snake_case(
    config_dir: object,
    write_config: Callable[[str], None],
) -> None:
    """The application derives snake_case event store and tracking table names."""
    write_config(f"database:\n  backend: postgres\n  postgres_dsn: {DSN}\n")

    with psycopg.connect(DSN or "") as connection, connection.cursor() as cursor:
        for table in (*TABLES, *OLD_TABLES):
            cursor.execute(f'DROP TABLE IF EXISTS "{table}" CASCADE')

    app = create_app()
    with TestClient(app):
        pass

    with psycopg.connect(DSN or "") as connection, connection.cursor() as cursor:
        cursor.execute(
            "SELECT table_name FROM information_schema.tables "
            "WHERE table_schema = 'public' AND "
            "(table_name LIKE 'catalog%' OR table_name LIKE 'ingestion%' "
            "OR table_name LIKE 'vocabulary%' OR table_name LIKE 'semantic%' "
            "OR table_name LIKE 'comment%' OR table_name LIKE 'iam%' "
            "OR table_name LIKE 'llm_config%' OR table_name LIKE 'conversation%' "
            "OR table_name IN ('checkpoints', 'checkpoint_writes'))"
        )
        found = {row[0] for row in cursor.fetchall()}

    assert set(TABLES) <= found
    for old_table in OLD_TABLES:
        assert old_table not in found
